//! bsl6 (v22exec5, 2026-11-02): send REAL InitMarket instruction bytes (generated by the seed kit's
//! `initMarketData` and the app wizard's `encodeInitMarketDataWithV22`) to a wrapper `.so` in LiteSVM and
//! record what the program answers. Evidence harness only (not CI): run with
//!   BSL6_SO=<percolator_prog.so> BSL6_ROWS=<rows.json> BSL6_OUT=<out.json> cargo test --test bsl6_initmarket_matrix -- --ignored
//! Each row: { "id", "slots", "decimals", "dataHex" }. Output: [{ "id", "result" }] with result "ok" or the
//! error string (e.g. "Custom(106)").
use litesvm::LiteSVM;
use percolator_prog::state;
use solana_sdk::{
    account::Account,
    compute_budget::ComputeBudgetInstruction,
    instruction::{AccountMeta, Instruction},
    program_option::COption,
    program_pack::Pack,
    pubkey::Pubkey,
    signature::{Keypair, Signer},
    transaction::Transaction,
};
use spl_token::state::{Account as TokenAccount, AccountState, Mint};
use std::path::PathBuf;

fn spl_token_program_path() -> PathBuf {
    let cargo_home = std::env::var_os("CARGO_HOME").map(PathBuf::from).unwrap_or_else(|| {
        let mut home = PathBuf::from(std::env::var_os("HOME").expect("HOME"));
        home.push(".cargo");
        home
    });
    let registry_src = cargo_home.join("registry/src");
    for registry in std::fs::read_dir(&registry_src).expect("registry/src") {
        let candidate = registry.expect("entry").path().join("litesvm-0.1.0/src/spl/programs/spl_token-3.5.0.so");
        if candidate.exists() {
            return candidate;
        }
    }
    panic!("LiteSVM SPL Token BPF not found");
}

fn hex_decode(s: &str) -> Vec<u8> {
    (0..s.len()).step_by(2).map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex")).collect()
}

fn acct(data: Vec<u8>, owner: Pubkey) -> Account {
    Account { lamports: 1_000_000_000, data, owner, executable: false, rent_epoch: 0 }
}

#[test]
#[ignore]
fn bsl6_initmarket_matrix() {
    let so = std::env::var("BSL6_SO").expect("BSL6_SO");
    let rows: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(std::env::var("BSL6_ROWS").expect("BSL6_ROWS")).unwrap()).unwrap();
    let mut svm = LiteSVM::new();
    let program_id = percolator_prog::id();
    svm.add_program(program_id, &std::fs::read(&so).expect("read .so"));
    svm.add_program(spl_token::ID, &std::fs::read(spl_token_program_path()).unwrap());
    let payer = solana_sdk::signer::keypair::keypair_from_seed(&[1u8; 32]).unwrap();
    let admin = solana_sdk::signer::keypair::keypair_from_seed(&[2u8; 32]).unwrap();
    svm.airdrop(&payer.pubkey(), 100_000_000_000_000).unwrap();
    svm.airdrop(&admin.pubkey(), 1_000_000_000).unwrap();
    let ata_program: Pubkey = "ATokenGPvbdGVxr1b2hvZbsiqW5xWH25efTNsLJA8knL".parse().unwrap();
    let mut out = Vec::new();
    for (i, row) in rows.as_array().expect("array").iter().enumerate() {
        let id = row["id"].as_str().unwrap().to_string();
        let slots = row["slots"].as_u64().unwrap() as usize;
        let decimals = row["decimals"].as_u64().unwrap() as u8;
        let data = hex_decode(row["dataHex"].as_str().unwrap());
        let mut seed = [0u8; 32];
        seed[..8].copy_from_slice(&(i as u64 + 1).to_le_bytes());
        seed[31] = 0x11;
        let market_kp = solana_sdk::signer::keypair::keypair_from_seed(&seed).unwrap();
        let market = market_kp.pubkey();
        let mut mseed = seed;
        mseed[31] = 0x12;
        let mint = solana_sdk::signer::keypair::keypair_from_seed(&mseed).unwrap().pubkey();
        let mut md = vec![0u8; Mint::LEN];
        Mint::pack(Mint { mint_authority: COption::None, supply: 0, decimals, is_initialized: true, freeze_authority: COption::None }, &mut md).unwrap();
        svm.set_account(mint, acct(md, spl_token::ID)).unwrap();
        let va = Pubkey::find_program_address(&[b"vault", market.as_ref()], &program_id).0;
        let vault = Pubkey::find_program_address(&[va.as_ref(), spl_token::ID.as_ref(), mint.as_ref()], &ata_program).0;
        let mut td = vec![0u8; TokenAccount::LEN];
        TokenAccount::pack(
            TokenAccount { mint, owner: va, amount: 0, delegate: COption::None, state: AccountState::Initialized, is_native: COption::None, delegated_amount: 0, close_authority: COption::None },
            &mut td,
        )
        .unwrap();
        svm.set_account(vault, acct(td, spl_token::ID)).unwrap();
        svm.set_account(market, acct(vec![0u8; state::market_account_len_for_capacity(slots).unwrap()], program_id)).unwrap();
        let ix = Instruction {
            program_id,
            accounts: vec![AccountMeta::new(admin.pubkey(), true), AccountMeta::new(market, true), AccountMeta::new_readonly(mint, false)],
            data,
        };
        svm.expire_blockhash();
        let tx = Transaction::new_signed_with_payer(
            &[ComputeBudgetInstruction::request_heap_frame(128 * 1024), ComputeBudgetInstruction::set_compute_unit_limit(1_400_000), ix],
            Some(&payer.pubkey()),
            &[&payer, &admin, &market_kp],
            svm.latest_blockhash(),
        );
        let result = match svm.send_transaction(tx) {
            Ok(_) => "ok".to_string(),
            Err(e) => {
                if std::env::var_os("BSL6_LOGS").is_some() {
                    eprintln!("{id}: {:?}", e.meta.logs);
                }
                let s = format!("{:?}", e.err);
                match s.find("Custom(") {
                    Some(p) => s[p..].split(')').next().unwrap().to_string() + ")",
                    None => s,
                }
            }
        };
        out.push(serde_json::json!({ "id": id, "result": result }));
    }
    std::fs::write(std::env::var("BSL6_OUT").expect("BSL6_OUT"), serde_json::to_string(&out).unwrap()).unwrap();
    eprintln!("bsl6: {} rows", out.len());
}
